         fun manualScan() {
             imageLongPress = { manualScan() }
             ocrJob?.cancel()
             // v1.9.40: НЕ автоскан всего экрана (с шапкой и рекламой) и НЕ только
             // картинки: пользователь сам рисует область пальцем на замороженном кадре.
             val raw = captureWebView()
