                     val tabId = activeTabId ?: webTabs.lastOrNull()?.id ?: return@AndroidView
                     val item = webTabs.firstOrNull { it.id == tabId }
                     val wv = webViewForTab(fl.context, tabId, item?.url ?: HOME_URL)
