                         fl.removeAllViews()
                         fl.addView(wv, android.widget.FrameLayout.LayoutParams(-1, -1))
                         // БЕЗ onPause()/onResume-потерь: музыка продолжает играть
                         wv.onResume()
                         canGoBackState.value = wv.canGoBack()
                         wv.url?.let { urlState.value = it }
                     }
                 },
                 onRelease = { fl ->
