                     imageHeight = sourceHeight,
                     regions = croppedResult.regions.mapNotNull { region ->
                         OcrBoxGeometry.restoreVerticalCrop(
                             box = region.boundingBox,
                             sourceHeight = sourceHeight,
                             cropTop = cropTop,
                             cropHeight = cropHeight,
