private suspend fun getEngine(): YoloPanelDetectionEngine {
    return engineMutex.withLock { engineLocked() }
}

/** Движок под [engineMutex]: сам замок здесь не берём — он не реентрантный. */
private fun engineLocked(): YoloPanelDetectionEngine {
    return engine ?: run {
        val modelPath = yomikai.data.ocr.OcrModelFiles.resolve(context, EXTERNAL_MODEL_PATH)
            ?: embeddedModelProvider?.invoke()
            ?: error(
                "Panel detector model not found: install externally " +
                    "(ocr_models/panel_detector.tflite) or embedded pack failed",
            )
        YoloPanelDetectionEngine(context, environment, modelPath).also { engine = it }
    }
}

