    private var engine: YoloPanelDetectionEngine? = null
    private val engineMutex = Mutex()

    /** Движок под [engineMutex]: сам замок здесь не берём — он не реентрантный. */
    private suspend fun engineLocked(): YoloPanelDetectionEngine {
        return engine ?: run {
            val modelPath = yomikai.data.ocr.OcrModelFiles.resolve(context, EXTERNAL_MODEL_PATH)
                ?: embeddedModelProvider?.invoke()
                ?: error(
                    "Panel detector model not found: install externally " +
                        "(ocr_models/panel_detector.tflite) or embedded pack failed",
                )
            YoloPanelDetectionEngine(context, environment, modelPath).also { engine = it }
        }
    }

    private companion object {
        const val EXTERNAL_MODEL_PATH = "panel_detector/model.tflite"
    }

    override suspend fun detectPanels(
        cacheKey: String,
        image: Bitmap,
        originalWidth: Int,
        originalHeight: Int,
        direction: ReadingDirection,
    ): PanelDetectionResult {
        return try {
            // engineMutex держится на ВЕСЬ вызов: cleanup() с главного потока
            // обязан дождаться конца инференса, иначе он закроет нативную
            // модель и переиспользуемый scratch-буфер прямо под ней.
            engineMutex.withLock {
                engineLocked().detectPanels(
                    cacheKey = cacheKey,
                    image = image,
                    originalWidth = originalWidth,
                    originalHeight = originalHeight,
=== cleanup ===
        } catch (e: Throwable) {
            logcat(LogPriority.WARN, e) { "Panel detection failed for $cacheKey" }
            PanelDetectionResult.EMPTY
        }
    }

    override fun cleanup() {
        // cleanup() зовут из onTrimMemory и onCleared, то есть с главного потока
        // и обычно в разгар авточтения. Раньше close() закрывал нативную модель
        // и переиспользовал scratch-пока прямо внутри detectPanels — это
        // use-after-free в нативе. Теперь вытесняем текущее распознавание
        // (engineMutex держится на весь вызов detectPanels) и закрываем после.
        val toClose = runBlocking(Dispatchers.IO) {
            engineMutex.withLock { engine.also { engine = null } }
        }
        runCatching { toClose?.close() }
            .onSuccess { logcat(LogPriority.INFO) { "PanelDetectionRepositoryImpl cleaned up successfully" } }
            .onFailure { logcat(LogPriority.ERROR) { "Error cleaning up panel detector" } }
    }
}

