internal fun redactSecrets(text: String): String = SECRET_FIELD_RE.replace(text) { m ->
    val key = m.groupValues[1]
    // Группа 2 — значение ВМЕСТЕ с кавычками, поэтому берём только сам
    // символ кавычки: иначе «замазанное» значение осталось бы в ответе
    // целиком рядом с меткой.
    val quote = m.groupValues[2].firstOrNull()?.toString().orEmpty()
    "$key$quote[скрыто агентом]$quote"
}

private val SECRET_READ_DENY = listOf("providers")

internal fun secretGuard(name: String): String? {
    val rel = name.trim().trimStart('/').lowercase()
    val denied = SECRET_READ_DENY.firstOrNull { dir ->
        rel == dir || rel.startsWith("$dir/") || rel.contains("/$dir/")
    }
        ?: return null
    return "ОТКАЗ: «$name» закрыт для чтения агентом (там ключи провайдеров). " +
        "Ключ меняется только через provider_edit, список провайдеров — через " +
        "provider_list. Сам файл не показан."
}

