        }
        searchAttempts += calls.count { it.name == "web_search" }
        if (calls.isEmpty()) {
            val why = skipped.joinToString(", ") { (c, r) -> "${c.name}: $r" }.take(240)
            answer = stripToolSyntax(context, answer).ifBlank {
