/**
 * Вкладка «AI»: один слой — токен и запуск. После запуска в этой же вкладке
 * открывается сайт-хаб npm-hub (дашборд / терминал / файлы / git / инструменты)
 * с GitHub-ранера, где живут CLI-агенты. Агент НЕ форсится при запуске —
 * пользователь сам выбирает и устанавливает его внутри хаба (как в оригинале).
 */
data object AiChatTab : Tab {

    override val options: TabOptions
        @Composable
        get() = TabOptions(
            index = 9u,
            title = "AI",
            icon = rememberVectorPainter(Icons.Outlined.SmartToy),
        )

    // Запуск переживает уход со вкладки и сворачивание приложения
    private val chatScope = kotlinx.coroutines.CoroutineScope(
        kotlinx.coroutines.SupervisorJob() + Dispatchers.IO,
    )
    private val hubStatusFlow = MutableStateFlow("")
    private val hubStartingFlow = MutableStateFlow(false)
    // Fix 5: активная сессия живёт на уровне ОБЪЕКТА, а не в remember —
    // при переключении вкладки (и обратно) WebView не «теряется».
    private val hubSessionFlow = MutableStateFlow<RunnerLlm.Session?>(null)

    private fun rememberSession(s: RunnerLlm.Session) {
        hubSessionFlow.value = s
    }

    @Composable
    override fun Content() {
        val context = LocalContext.current
        val prefs = remember { Injekt.get<OcrPreferences>() }
        val pat by prefs.githubPat().changes().collectAsState(initial = prefs.githubPat().get())
        val starting by hubStartingFlow.collectAsState()
        val status by hubStatusFlow.collectAsState()
        val session by hubSessionFlow.collectAsState()
        var sessions by remember {
            mutableStateOf(runCatching { RunnerLlm.listSessions(context) }.getOrDefault(emptyList()))
        }
        // Лента событий ранера: последние прогоны и пошаговая лента задач.
        // Читатель просил видеть, что ранер делал, не выспрашивая агента.
        var events by remember { mutableStateOf<List<AiGithub.Run>>(emptyList()) }
        var eventsLoading by remember { mutableStateOf(false) }
        var eventsError by remember { mutableStateOf("") }

        val loadEvents: () -> Unit = {
            if (pat.isBlank()) {
                eventsError = "Сначала вставьте GitHub PAT"
            } else {
                eventsLoading = true
                eventsError = ""
                val token = pat.trim()
                chatScope.launch {
                    val got = runCatching { AiGithub.runs(token, AiGithub.DEFAULT_REPO, perPage = 8) }
                        .getOrElse { emptyList() }
                    withContext(Dispatchers.Main) {
                        events = got
                        eventsLoading = false
                        if (got.isEmpty() && eventsError.isBlank()) {
                            eventsError = "Прогонов не найдено или сеть недоступна"
                        }
                    }
                }
            }
        }

        val openSession = session
        if (openSession != null) {
            HubWebView(
                session = openSession,
                onClose = { hubSessionFlow.value = null },
            )
        } else {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .statusBarsPadding()
                    .imePadding()
                    .verticalScroll(rememberScrollState())
                    .padding(16.dp),
                verticalArrangement = Arrangement.spacedBy(12.dp),
            ) {
                Text("OpenCode-агент", style = MaterialTheme.typography.titleMedium)
                Text(
                    "Запускает сайт-хаб (npm-hub) на GitHub-ранере: дашборд, терминал, " +
                        "файлы, git, инструменты. Нужного CLI-агента (opencode, DeepSeek, UTIM, " +
                        "AI Shell и др.) вы сами выбираете и устанавливаете прямо внутри хаба. " +
                        "Ранер работает вашим PAT аккаунта, поэтому видит и меняет ВСЕ репозитории " +
                        "аккаунта. Нужен PAT с правом actions:write.",
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                )
                OutlinedTextField(
                    value = pat,
                    onValueChange = { token ->
                        // Пробелы по краям ломают GitHub Auth: token = " ghp_…x "
                    // считается невалидным и старт сессии падает с 401.
                        prefs.githubPat().set(token.trim())
                    },
                    label = { Text("GitHub PAT") },
                    modifier = Modifier.fillMaxWidth(),
                    maxLines = 1,
                )
                var elapsed by remember { mutableStateOf(0L) }
                LaunchedEffect(starting) {
                    elapsed = 0
                    while (starting) {
                        delay(1000)
                        elapsed++
                    }
                }
                FilledTonalButton(
                    enabled = !starting && pat.isNotBlank(),
                    onClick = {
                        val trimmed = pat.trim()
                        val looksLikePat = trimmed.startsWith("ghp_") ||
                            trimmed.startsWith("github_pat_") ||
                            trimmed.startsWith("gho_") ||
                            trimmed.startsWith("ghs_") ||
                            trimmed.startsWith("ghr_")
                        if (!looksLikePat) {
                            hubStatusFlow.value =
                                "❌ Токен не похож на GitHub PAT. Нужен токен, " +
                                "начинающийся на ghp_ / github_pat_ / gho_ (Settings → Developer settings → " +
                                "Personal access tokens). Вставлен Discord- или другой токен?"
                            return@FilledTonalButton
                        }
                        hubStartingFlow.value = true
                        hubStatusFlow.value = "⏳ Запуск хаба npm-hub…"
                        val appCtx = context.applicationContext
                        chatScope.launch {
                            val s = runCatching {
                                RunnerLlm.startOpenCode(
                                    appCtx,
                                    { st -> hubStatusFlow.value = st },
                                    os = "linux",
                                    ui = "mobile",
                                )
                            }.getOrElse {
                                hubStatusFlow.value = "❌ Ошибка запуска: ${it.message ?: it}"
                                null
                            }
                            withContext(Dispatchers.Main) {
                                hubStartingFlow.value = false
                                if (s != null) {
                                    sessions = runCatching { RunnerLlm.listSessions(context) }
                                        .getOrDefault(emptyList())
                                    rememberSession(s)
                                }
                            }
                        }
                    },
                ) { Text(if (starting) "Запускаем…" else "▶ Запустить") }
                if (status.isNotBlank()) {
                    Text(
                        if (starting) "$status • ${elapsed / 60}:${"%02d".format(elapsed % 60)}"
                        else status,
                        style = MaterialTheme.typography.bodySmall,
                    )
                }
                // Лента событий ранера. Раньше читатель видел только «сессии»
                // и кнопку «Открыть»: что ранер делал внутри прогона, не было
                // видно нигде, хотя GitHub Actions это знает.
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    FilterChip(
                        selected = events.isNotEmpty(),
                        onClick = { loadEvents() },
                        label = { Text("События ранера") },
                    )
                    if (eventsLoading) {
                        Text("Загрузка…", style = MaterialTheme.typography.labelSmall)
                    }
                }
                if (eventsError.isNotBlank()) {
                    Text(
                        eventsError,
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                    )
                }
                events.forEach { r ->
                    var steps by remember(r.id) { mutableStateOf<String?>(null) }
                    var stepsLoading by remember(r.id) { mutableStateOf(false) }
                    Column(modifier = Modifier.fillMaxWidth().padding(vertical = 2.dp)) {
                        Text(
                            "#${r.id} ${r.name} — ${r.stateRu}",
                            style = MaterialTheme.typography.bodySmall,
                        )
                        Text(
                            "Показать шаги",
                            style = MaterialTheme.typography.labelSmall,
                            color = MaterialTheme.colorScheme.primary,
                            modifier = Modifier.clickable {
                                if (steps != null || stepsLoading) return@clickable
                                stepsLoading = true
                                val token = pat.trim()
                                val runId = r.id
                                chatScope.launch {
                                    val text = runCatching {
                                        AiGithub.renderJobs(AiGithub.jobs(token, runId))
                                    }.getOrElse { "Не удалось прочитать шаги: ${it.message}" }
                                    withContext(Dispatchers.Main) {
                                        steps = text
                                        stepsLoading = false
                                    }
                                }
                            },
                        )
                        if (stepsLoading) {
                            Text("…", style = MaterialTheme.typography.labelSmall)
                        }
                        steps?.let { txt ->
                            Text(
                                txt,
                                style = MaterialTheme.typography.labelSmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant,
                            )
                        }
                    }
                }
                if (sessions.isNotEmpty()) {
                    Text("Сессии:", style = MaterialTheme.typography.bodySmall)
                    sessions.forEach { s ->
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                        ) {
                            Text(
                                "${s.model} • ${s.messages.size} сообщ. • ${s.os}",
                                style = MaterialTheme.typography.bodySmall,
                                modifier = Modifier.weight(1f),
                            )
                            if (s.terminalUrl != null || s.url != null) {
                                FilterChip(
                                    selected = false,
                                    onClick = { rememberSession(s) },
                                    label = { Text("Открыть") },
                                )
                            }
                            FilterChip(
                                selected = false,
                                onClick = {
                                    runCatching {
                                        RunnerLlm.deleteSession(context, s)
                                        sessions = RunnerLlm.listSessions(context)
                                    }
                                },
                                label = { Text("✕") },
                            )
                        }
                    }
                }
            }
        }
    }

    /** Сайт-хаб npm-hub в той же вкладке: loading-экран вместо чёрного + ошибки. */
    @Composable
    @android.annotation.SuppressLint("SetJavaScriptEnabled")
    private fun HubWebView(
        session: RunnerLlm.Session,
        onClose: () -> Unit,
    ) {
        val context = LocalContext.current
        val url = session.terminalUrl ?: session.url.orEmpty()
        var loading by remember(session.id) { mutableStateOf(true) }
        var error by remember(session.id) { mutableStateOf<String?>(null) }
        val webView = remember(session.id, url) {
            runCatching {
                WebView(context).apply {
                    // На чёрном фоне «протухающий» туннель выглядел как мёртвый экран.
                    setBackgroundColor(android.graphics.Color.WHITE)
                    isFocusable = true
                    isFocusableInTouchMode = true
                    settings.javaScriptEnabled = true
                    settings.domStorageEnabled = true
                    settings.loadWithOverviewMode = false
                    settings.useWideViewPort = false
                    settings.builtInZoomControls = false
                    settings.displayZoomControls = false
                    settings.mixedContentMode = android.webkit.WebSettings.MIXED_CONTENT_ALWAYS_ALLOW
                    webViewClient = object : WebViewClient() {
                        override fun onReceivedHttpAuthRequest(
                            view: WebView?,
                            handler: HttpAuthHandler,
                            host: String?,
                            realm: String?,
                        ) {
                            runCatching { handler.proceed("yomikai", session.apiKey.orEmpty()) }
                        }

                        override fun onPageFinished(view: WebView?, url: String?) {
                            loading = false
                            error = null
                            view?.requestFocus()
                        }

                        override fun onReceivedError(
                            view: WebView?,
                            errorCode: Int,
                            description: String?,
                            failingUrl: String?,
                        ) {
                            loading = false
                            error = "Ошибка загрузки ($errorCode): $description"
                        }

                        override fun onReceivedHttpError(
                            view: WebView?,
                            request: android.webkit.WebResourceRequest?,
                            errorResponse: android.webkit.WebResourceResponse?,
                        ) {
                            loading = false
                            val code = errorResponse?.statusCode ?: 0
                            val mime = errorResponse?.mimeType.orEmpty()
                            // Discord api error format leaked through a proxy/token:
                            // {"success":false,"result":null,"errors":[{"code":10005,...}]}
                            val body = runCatching {
                                errorResponse?.data?.bufferedReader()?.use { it.readText() }.orEmpty()
                            }.getOrDefault("").take(300)
                            if (code == 405 || body.contains("method not allowed", ignoreCase = true)) {
                                error = "Ранер ответил $code (Method Not Allowed). Скорее всего в поле " +
                                    "GitHub PAT вставлен НЕ-GitHub токен (например Discord). Возьмите " +
                                    "настоящий GitHub PAT (ghp_/github_pat_). Ответ: $body"
                            } else {
                                error = "HTTP $code на сайте ранера" +
                                    body.takeIf { it.isNotBlank() }?.let { "\n$it" }.orEmpty()
                            }
                        }
                    }
                    if (url.isNotBlank()) loadUrl(url)
                }
            }.getOrElse {
                error = "WebView не создался: ${it.message ?: it}"
                null
            }
        }
        DisposableEffect(webView) {
            onDispose {
                runCatching {
                    (webView?.parent as? android.view.ViewGroup)?.removeView(webView)
                    webView?.stopLoading()
                    webView?.destroy()
                }
            }
        }

        Column(modifier = Modifier.fillMaxSize().statusBarsPadding()) {
            Row(
                modifier = Modifier.fillMaxWidth().padding(horizontal = 12.dp, vertical = 4.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(8.dp),
            ) {
                Text(
                    "npm-hub • ${session.os}" +
                        (if (loading) " • подключение…" else " • сайт"),
                    style = MaterialTheme.typography.bodySmall,
                    modifier = Modifier.weight(1f),
                )
                IconButton(onClick = {
                    loading = true
                    error = null
                    runCatching { webView?.reload() }
                }) {
                    Icon(Icons.Outlined.Refresh, contentDescription = "Перезагрузить")
                }
                TextButton(onClick = onClose) { Text("Закрыть") }
            }
            if (webView != null && error == null) {
                AndroidView(
                    factory = { webView },
                    modifier = Modifier.fillMaxSize(),
                )
            } else {
                Column(
                    modifier = Modifier.fillMaxSize().padding(24.dp),
                    verticalArrangement = Arrangement.Center,
                    horizontalAlignment = Alignment.CenterHorizontally,
                ) {
                    Text(
                        error ?: "Сайт хаба недоступен. Проверьте, что ранер ещё жив.",
                        style = MaterialTheme.typography.bodyMedium,
                    )
                    FilledTonalButton(
                        onClick = { error = null; loading = true; runCatching { webView?.reload() } },
                    ) { Text("Попробовать снова") }
                    TextButton(onClick = onClose) { Text("Закрыть и к запуску") }
                }
            }
        }
    }
}

package yomikai.data.ai

import android.content.Context
import yomikai.data.books.BookParser
import yomikai.data.books.BooksStore
import yomikai.data.tts.VoiceHelper
import yomikai.data.tts.VoiceKind
import kotlinx.coroutines.runBlocking
import yomikai.domain.ocr.service.OcrPreferences
import logcat.LogPriority
import org.json.JSONArray
import org.json.JSONObject
import yomikai.core.common.util.system.logcat
import java.io.BufferedReader
import java.io.InputStreamReader
import java.io.OutputStream
import java.net.InetSocketAddress
import java.net.ServerSocket
import java.net.Socket
import java.net.URLDecoder
import java.util.UUID
import uy.kohesive.injekt.Injekt
import uy.kohesive.injekt.api.get

/**
 * Мини HTTP-сервер AI-агента и внешних инструментов.
 *
 * Endpoints:
 *  GET  /            — страница чата (HTML+JS)
 *  POST /chat        — {"text": "..."} → ответ агента JSON
 *  GET  /files       — список файлов workspace (JSON)
 *  GET  /file?p=rel  — скачать файл workspace
 *  GET  /tts/voices  — список голосов TTS
 *  POST /tts/voice   — установить голос
 *  GET  /ocr/settings — настройки OCR
 *  POST /ocr/settings — обновить настройки OCR
 *  GET  /books/list   — список книг с метаданными
 *  POST /books/import — импорт книги по URL (потоковый, без OOM)
 *  GET  /books/metadata?uri=... — метаданные книги
 *  GET  /books/cover?uri=... — обложка книги (PNG)
 */
object AiHttpServer {

    const val PORT = 8765

    fun tokenFor(context: Context): String {
        val prefs = Injekt.get<OcrPreferences>()
        val existing = prefs.aiHttpToken().get()
        if (existing.isNotBlank()) return existing
        val generated = UUID.randomUUID().toString().replace("-", "").take(16)
        prefs.aiHttpToken().set(generated)
        logcat(LogPriority.INFO) { "AiHttpServer: сгенерирован ключ доступа" }
        return generated
    }

    @Volatile
    private var server: ServerSocket? = null
    private var thread: Thread? = null

    val isRunning: Boolean get() = server?.isClosed == false

    @Synchronized
    fun start(context: Context) {
        if (isRunning) return
        val appContext = context.applicationContext
        val ss = ServerSocket()
        ss.reuseAddress = true
        ss.bind(InetSocketAddress("0.0.0.0", PORT))
        tokenFor(appContext)
        server = ss
        thread = Thread {
            while (!ss.isClosed) {
                try {
                    val client = ss.accept()
                    Thread { handle(appContext, client) }.start()
                } catch (e: Exception) {
                    if (!ss.isClosed) logcat(LogPriority.WARN, e) { "AiHttpServer accept failed" }
                }
            }
        }.apply {
            isDaemon = true
            name = "AiHttpServer"
            start()
        }
        logcat(LogPriority.INFO) { "AiHttpServer started on :$PORT" }
    }

    @Synchronized
    fun stop() {
        runCatching { server?.close() }
        server = null
        thread = null
    }

    private fun handle(context: Context, socket: Socket) {
        socket.use { s ->
            runCatching {
                s.soTimeout = 180_000
                val reader = BufferedReader(InputStreamReader(s.getInputStream(), Charsets.UTF_8))
                val requestLine = reader.readLine() ?: return
                val parts = requestLine.split(" ")
                if (parts.size < 2) return
                val method = parts[0]
                val fullPath = parts[1]
                var contentLength = 0
                while (true) {
                    val h = reader.readLine() ?: break
                    if (h.isBlank()) break
                    if (h.startsWith("Content-Length:", true)) {
                        contentLength = h.substringAfter(':').trim().toIntOrNull() ?: 0
                    }
                }
                val body = if (method == "POST" && contentLength > 0) {
                    val buf = CharArray(contentLength.coerceAtMost(1 shl 20))
                    var read = 0
                    while (read < buf.size) {
                        val n = reader.read(buf, read, buf.size - read)
                        if (n < 0) break
                        read += n
                    }
                    String(buf, 0, read)
                } else {
                    ""
                }

                val out = s.getOutputStream()

                if (queryParam(fullPath.substringAfter('?', ""), "key") != tokenFor(context)) {
                    respond(
                        out,
                        401,
                        "text/plain; charset=utf-8",
                        "401 Unauthorized\n\nОткройте ссылку с ключом из приложения:\nвкладка AI — блок «Доступ из внешнего браузера».".toByteArray(),
                    )
                    return
                }

                val path = fullPath.substringBefore('?')
                val query = fullPath.substringAfter('?', "")
                when {
                    method == "GET" && path == "/" -> respond(out, 200, "text/html; charset=utf-8", PAGE.toByteArray())
                    method == "POST" && path == "/chat" -> {
                        val text = runCatching { JSONObject(body).optString("text") }.getOrDefault("")
                        val reply = runBlocking { AiAgent.run(context, text) }
                        val json = JSONObject()
                            .put("text", reply.text)
                            .put("tools", JSONArray(reply.toolResults.map { "${it.name}: ${it.output}" }))
                            .put("images", JSONArray(reply.images.map { AiWorkspace.relPath(context, it) }))
                        respond(out, 200, "application/json; charset=utf-8", json.toString().toByteArray())
                    }
                    method == "GET" && path == "/tts/voices" -> {
                        val language = queryParam(query, "lang")?.ifBlank { "ru" } ?: "ru"
                        val prefs = Injekt.get<OcrPreferences>()
                        val voices = JSONArray()
                        VoiceHelper.localCatalog(language).forEach { voice ->
                            val gender = when (VoiceHelper.classify(voice)) {
                                VoiceKind.FEMALE -> "female"
                                VoiceKind.MALE -> "male"
                                VoiceKind.TEEN -> "teen"
                                VoiceKind.OTHER -> "other"
                            }
                            voices.put(
                                JSONObject()
                                    .put("name", voice.name)
                                    .put("language", voice.locale.toLanguageTag())
                                    .put("gender", gender)
                                    .put("local", true),
                            )
                        }
                        val json = JSONObject()
                            .put("engine", prefs.systemTtsEngine().get())
                            .put("selected", prefs.voiceName().get())
                            .put("female", prefs.voiceFemale().get())
                            .put("male", prefs.voiceMale().get())
                            .put("voices", voices)
                        respond(out, 200, "application/json; charset=utf-8", json.toString().toByteArray())
                    }
                    method == "POST" && path == "/tts/voice" -> {
                        val request = runCatching { JSONObject(body) }.getOrDefault(JSONObject())
                        val name = request.optString("name").trim()
                        val language = request.optString("lang").ifBlank { "ru" }
                        val slot = request.optString("slot").ifBlank { "main" }
                        val valid = VoiceHelper.localCatalog(language).any { it.name == name }
                        if (!valid) {
                            respond(out, 400, "application/json", "{\"error\":\"unknown voice\"}".toByteArray())
                        } else {
                            val prefs = Injekt.get<OcrPreferences>()
                            when (slot) {
                                "female" -> prefs.voiceFemale().set(name)
                                "male" -> prefs.voiceMale().set(name)
                                else -> prefs.voiceName().set(name)
                            }
                            respond(out, 200, "application/json", "{\"ok\":true}".toByteArray())
                        }
                    }
                    method == "GET" && path == "/files" -> {
                        val arr = JSONArray()
                        AiWorkspace.listAll(context).filter { it.isFile }.forEach {
                            arr.put(
                                JSONObject()
                                    .put("path", AiWorkspace.relPath(context, it))
                                    .put("size", it.length()),
                            )
                        }
                        respond(out, 200, "application/json; charset=utf-8", arr.toString().toByteArray())
                    }
                    method == "GET" && path == "/ocr/settings" -> {
                        val prefs = Injekt.get<OcrPreferences>()
                        val json = JSONObject()
                            .put("contentType", prefs.contentType().get())
                            .put("autoPreset", prefs.autoPreset().get())
                            .put("scanRegion", prefs.presetScanRegion().get())
                            .put("readingOrder", prefs.scanReadingOrder().get())
                            .put("autoReadLanguage", prefs.autoReadLanguage().get())
                            .put("autoReadTranslate", prefs.autoReadTranslate().get())
                            .put("voiceIcons", prefs.voiceIcons().get())
                            .put("showSpeechNumbers", prefs.showSpeechNumbers().get())
                            .put("aiGenderVoices", prefs.aiGenderVoices().get())
                            .put("voiceEngine", prefs.voiceEngine().get())
                            .put("voiceName", prefs.voiceName().get())
                            .put("systemTtsEngine", prefs.systemTtsEngine().get())
                        respond(out, 200, "application/json; charset=utf-8", json.toString().toByteArray())
                    }
                    method == "POST" && path == "/ocr/settings" -> {
                        val prefs = Injekt.get<OcrPreferences>()
                        val request = runCatching { JSONObject(body) }.getOrDefault(JSONObject())
                        if (request.has("contentType")) prefs.contentType().set(request.optString("contentType"))
                        if (request.has("autoPreset")) prefs.autoPreset().set(request.optString("autoPreset"))
                        if (request.has("scanRegion")) prefs.presetScanRegion().set(request.optString("scanRegion"))
                        if (request.has("readingOrder")) prefs.scanReadingOrder().set(request.optString("readingOrder"))
                        if (request.has("autoReadLanguage")) prefs.autoReadLanguage().set(request.optString("autoReadLanguage"))
                        if (request.has("autoReadTranslate")) prefs.autoReadTranslate().set(request.optBoolean("autoReadTranslate"))
                        if (request.has("voiceIcons")) prefs.voiceIcons().set(request.optBoolean("voiceIcons"))
                        respond(out, 200, "application/json", "{\"ok\":true}".toByteArray())
                    }

                    // ---- Books API ----
                    method == "GET" && path == "/books/list" -> {
                        val arr = JSONArray()
                        BooksStore.listBooks(context).forEach { file ->
                            val snap = BooksStore.load(context, file)
                            val metadata = BooksStore.loadMetadata(context, file)
                            arr.put(
                                JSONObject()
                                    .put("name", file.name.orEmpty())
                                    .put("uri", file.uri.toString())
                                    .put("title", metadata.title)
                                    .put("author", metadata.author ?: "")
                                    .put("ext", file.name.orEmpty().substringAfterLast('.', "").uppercase())
                                    .put("progressPercent", snap.percent)
                                    .put("chapter", snap.chapter)
                                    .put("sentence", snap.sentence),
                            )
                        }
                        respond(out, 200, "application/json; charset=utf-8", arr.toString().toByteArray())
                    }
                    method == "POST" && path == "/books/import" -> {
                        val request = runCatching { JSONObject(body) }.getOrDefault(JSONObject())
                        val url = request.optString("url").trim()
                        val name = request.optString("name").trim()
                        if (url.isBlank()) {
                            respond(out, 400, "application/json", "{\"error\":\"empty url\"}".toByteArray())
                        } else {
                            val result = importBookFromUrl(context, url, name.ifBlank { null })
                            respond(
                                out,
                                if (result is BooksStore.ImportResult.Success) 200 else 400,
                                "application/json; charset=utf-8",
                                when (result) {
                                    is BooksStore.ImportResult.Success -> {
                                        val metadata = BooksStore.loadMetadata(context, result.book)
                                        JSONObject()
                                            .put("ok", true)
                                            .put("name", result.book.name.orEmpty())
                                            .put("title", metadata.title)
                                            .put("author", metadata.author ?: "")
                                            .toString()
                                    }
                                    is BooksStore.ImportResult.Failure ->
                                        JSONObject().put("ok", false).put("error", result.reason).toString()
                                }.toByteArray(),
                            )
                        }
                    }
                    method == "GET" && path == "/books/metadata" -> {
                        val uri = queryParam(query, "uri")?.trim()
                        if (uri.isNullOrEmpty()) {
                            respond(out, 400, "application/json", "{\"error\":\"missing uri\"}".toByteArray())
                        } else {
                            val file = BooksStore.listBooks(context).find { it.uri.toString() == uri }
                            if (file == null) {
                                respond(out, 404, "application/json", "{\"error\":\"book not found\"}".toByteArray())
                            } else {
                                val metadata = BooksStore.loadMetadata(context, file)
                                val json = JSONObject()
                                    .put("title", metadata.title)
                                    .put("author", metadata.author ?: "")
                                    .put("description", metadata.description ?: "")
                                    .put("language", metadata.language ?: "")
                                    .put("publisher", metadata.publisher ?: "")
                                    .put("year", metadata.year ?: JSONObject.NULL)
                                    .put("genre", JSONArray(metadata.genre.orEmpty()))
                                    .put("hasCover", metadata.coverImage != null || BooksStore.coverPath(context, file) != null)
                                respond(out, 200, "application/json; charset=utf-8", json.toString().toByteArray())
                            }
                        }
                    }
                    method == "GET" && path == "/books/cover" -> {
                        val uri = queryParam(query, "uri")?.trim()
                        if (uri.isNullOrEmpty()) {
                            respond(out, 400, "text/plain", "missing uri".toByteArray())
                        } else {
                            val file = BooksStore.listBooks(context).find { it.uri.toString() == uri }
                            if (file == null) {
                                respond(out, 404, "text/plain", "book not found".toByteArray())
                            } else {
                                val coverPath = BooksStore.coverPath(context, file)
                                if (coverPath != null) {
                                    val coverFile = java.io.File(coverPath)
                                    if (coverFile.exists()) {
                                        respond(out, 200, "image/png", coverFile.readBytes())
                                    } else {
                                        serveCoverFromMetadata(out, context, file)
                                    }
                                } else {
                                    serveCoverFromMetadata(out, context, file)
                                }
                            }
                        }
                    }
                    method == "GET" && path == "/file" -> {
                        val rel = query.split('&')
                            .firstOrNull { it.startsWith("p=") }
                            ?.substringAfter('=')
                            ?.let { URLDecoder.decode(it, "UTF-8") }
                        val f = rel?.let { AiWorkspace.resolve(context, it) }
                        if (f?.isFile == true) {
                            val mime = when (f.extension.lowercase()) {
                                "jpg", "jpeg" -> "image/jpeg"
                                "png" -> "image/png"
                                "zip" -> "application/zip"
                                "txt", "md" -> "text/plain; charset=utf-8"
                                else -> "application/octet-stream"
                            }
                            respond(out, 200, mime, f.readBytes(), "attachment; filename=\"${f.name}\"")
                        } else {
                            respond(out, 404, "text/plain", "not found".toByteArray())
                        }
                    }
                    else -> respond(out, 404, "text/plain", "not found".toByteArray())
                }
            }.onFailure {
                logcat(LogPriority.WARN, it) { "AiHttpServer request failed" }
            }
        }
    }

    private fun queryParam(query: String, name: String): String? =
        query.split('&')
            .firstOrNull { it.substringBefore('=') == name }
            ?.substringAfter('=', "")
            ?.let { URLDecoder.decode(it, "UTF-8") }

    /** Отдаёт обложку из метаданных книги (если файл-кэш ещё не создан). */
    private fun serveCoverFromMetadata(
        out: OutputStream,
        context: Context,
        book: com.hippo.unifile.UniFile,
    ) {
        val meta = BooksStore.loadMetadata(context, book)
        val bytes = meta.coverImage
        if (bytes != null) {
            BooksStore.saveCover(context, book, bytes)
            respond(out, 200, "image/png", bytes)
        } else {
            respond(out, 404, "text/plain", "no cover".toByteArray())
        }
    }

    /**
     * Скачивает книгу по URL с потоковым чтением (без OOM).
     * Лимит: 40 МБ. Проверяет Content-Length и читает по чанкам.
     */
    private fun importBookFromUrl(
        context: Context,
        url: String,
        name: String?,
    ): BooksStore.ImportResult {
        val MAX_SIZE = 40 * 1024 * 1024L
        return try {
            val conn = java.net.URL(url).openConnection() as java.net.HttpURLConnection
            conn.connectTimeout = 15_000
            conn.readTimeout = 60_000
            conn.instanceFollowRedirects = true
            conn.connect()

            if (conn.responseCode !in 200..299) {
                return BooksStore.ImportResult.Failure("HTTP ${conn.responseCode}")
            }

            // Проверяем Content-Length до чтения
            val contentLength = conn.contentLengthLong.takeIf { it > 0 } ?: -1
            if (contentLength > MAX_SIZE) {
                conn.disconnect()
                return BooksStore.ImportResult.Failure("Файл слишком большой (${contentLength / 1024 / 1024} МБ, лимит 40 МБ)")
            }

            // Потоковое чтение с проверкой размера
            val baos = java.io.ByteArrayOutputStream()
            val buffer = ByteArray(8192)
            var totalRead = 0L
            conn.inputStream.use { input ->
                while (true) {
                    val read = input.read(buffer)
                    if (read < 0) break
                    totalRead += read
                    if (totalRead > MAX_SIZE) {
                        conn.disconnect()
                        return BooksStore.ImportResult.Failure("Файл больше 40 МБ")
                    }
                    baos.write(buffer, 0, read)
                }
            }

            // Заголовки и итоговый URL сохраняем ДО disconnect
            val disposition = conn.getHeaderField("Content-Disposition")
            val finalUrl = conn.url
            conn.disconnect()

            val fileName = when {
                !name.isNullOrBlank() -> name
                else -> {
                    val dispositionName = disposition?.let {
                        Regex("""filename[*]?=(?:"|UTF-8'')?([^"\s]+)""")
                            .find(it)?.groupValues?.get(1)
                            ?.let { raw ->
                                runCatching { URLDecoder.decode(raw, "UTF-8") }.getOrDefault(raw)
                                    .trim('"')
                            }
                    }
                    dispositionName
                        ?: finalUrl.path.substringAfterLast('/').ifBlank { null }
                        ?: "book_${System.currentTimeMillis()}"
                }
            }

            BooksStore.importBytes(context, fileName, baos.toByteArray())
        } catch (e: Exception) {
            BooksStore.ImportResult.Failure("Скачивание не удалось: ${e.message}")
        }
    }

    private fun respond(
        out: OutputStream,
        code: Int,
        contentType: String,
        body: ByteArray,
        disposition: String? = null,
    ) {
        val status = if (code == 200) "200 OK" else "$code Error"
        val headers = buildString {
            append("HTTP/1.1 $status\r\n")
            append("Content-Type: $contentType\r\n")
            append("Content-Length: ${body.size}\r\n")
            if (disposition != null) append("Content-Disposition: $disposition\r\n")
            append("Access-Control-Allow-Origin: *\r\n")
            append("Connection: close\r\n\r\n")
        }
        out.write(headers.toByteArray())
        out.write(body)
        out.flush()
    }

