import uy.kohesive.injekt.injectLazy
import java.security.Security

class App : Application(), DefaultLifecycleObserver, SingletonImageLoader.Factory {

    private val basePreferences: BasePreferences by injectLazy()
    private val networkPreferences: NetworkPreferences by injectLazy()

    private val disableIncognitoReceiver = DisableIncognitoReceiver()

    @SuppressLint("LaunchActivityFromNotification")
    override fun onCreate() {
        super<Application>.onCreate()
        patchInjekt()
        GlobalExceptionHandler.initialize(applicationContext, CrashActivity::class.java)

        // AI-агент из внешнего браузера: если сервер был включён — поднимаем
        // при старте (лениво, в фоне; сбой не мешает запуску приложения)
        Thread {
            runCatching {
                val ocrPrefs = uy.kohesive.injekt.Injekt.get<yomikai.domain.ocr.service.OcrPreferences>()
                if (ocrPrefs.aiHttpServer().get()) {
                    yomikai.data.ai.AiHttpServer.start(applicationContext)
                }
            }
        }.apply { name = "ai-http-init"; priority = Thread.MIN_PRIORITY }.start()

        // TLS 1.3 support for Android < 10
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.Q) {
            Security.insertProviderAt(Conscrypt.newProvider(), 1)
        }

        // Avoid potential crashes
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
            val process = getProcessName()
            if (packageName != process) WebView.setDataDirectorySuffix(process)
        }

        Injekt.importModule(PreferenceModule(this))
        Injekt.importModule(AppModule(this))
        Injekt.importModule(DomainModule())

        // Cyrillic PP-OCR is the default and only supported offline OCR. Its
        // ~21 MB model pack stays outside the APK and is fetched once. A failed
        // startup download can still be retried from Text Recognition settings.
        Thread {
            runCatching {
                val ocrPrefs = Injekt.get<yomikai.domain.ocr.service.OcrPreferences>()
                if (
                    ocrPrefs.ocrModel().get() in setOf(
                        yomikai.domain.ocr.model.OcrModel.LEGACY,
                        yomikai.domain.ocr.model.OcrModel.FAST,
                        yomikai.domain.ocr.model.OcrModel.TESSERACT,
                    )
                ) {
                    ocrPrefs.ocrModel().set(yomikai.domain.ocr.model.OcrModel.CYRILLIC)
                }
                val downloader = yomikai.data.ocr.OcrModelDownloader
                if (!downloader.isPackInstalled(applicationContext, "cyrillic_ocr")) {
                    downloader.downloadPack(applicationContext, "cyrillic_ocr")
                }
            }
        }.apply { name = "cyrillic-ocr-init"; priority = Thread.MIN_PRIORITY }.start()

        setupNotificationChannels()
        Thread { runCatching { Injekt.get<OcrScanManager>().startIfPending() } }
            .apply { name = "ocr-pending-init"; priority = Thread.MIN_PRIORITY }
            .start()

        // Пользовательский словарь OCR живёт в файле приложения: сюда
        // добавляются слова с карточки результата («＋ Словарь») и из настроек.
        // Обращается сразу после старта, чтобы фоновое распознавание и читалка
        // видели одни и те же слова.
        android.util.Log.d("OcrVocabulary", "configure(file=" +
            java.io.File(filesDir, "ocr_vocab.txt").absolutePath + ")")
        yomikai.data.ocr.OcrVocabulary.configure(
            java.io.File(filesDir, "ocr_vocab.txt").absolutePath,
        )

        // Буфер скриншотов авточтения (вкладка «Скриншоты»): загружает
        // сохранённые скрины и JPEG-файлы при старте приложения.
        yomikai.data.ocr.OcrScreenshotBuffer.init(applicationContext)
        // Лимит буфера скриншотов из настроек dev-панели.
        yomikai.data.ocr.OcrScreenshotBuffer.maxEntries = Injekt.get<yomikai.domain.ocr.service.OcrPreferences>()
            .screenshotBufferSize().get().coerceIn(10, 200)

        // Первый запуск без онбординга: сразу создаём основную папку
        // "Yomikai" на телефоне (как у CDisplayEx) и помечаем онбординг
        // пройденным — приложение открывается прямо в библиотеке.
        Thread {
            runCatching {
                val prefs = basePreferences
                if (!prefs.shownOnboardingFlow.get()) {
                    val dir = java.io.File(
                        android.os.Environment.getExternalStorageDirectory(),
                        "Yomikai",
                    )
                    dir.mkdirs()
                    java.io.File(dir, "local").mkdirs()
                    java.io.File(dir, "downloads").mkdirs()
                    java.io.File(dir, "backup").mkdirs()
                    prefs.shownOnboardingFlow.set(true)
                }
            }
        }.apply { name = "first-run-setup"; priority = Thread.MIN_PRIORITY }.start()

        ProcessLifecycleOwner.get().lifecycle.addObserver(this)

        val scope = ProcessLifecycleOwner.get().lifecycleScope

        // Show notification to disable Incognito Mode when it's enabled
        basePreferences.incognitoMode.changes()
            .onEach { enabled ->
                if (enabled) {
                    disableIncognitoReceiver.register()
                    notify(
                        Notifications.ID_INCOGNITO_MODE,
                        Notifications.CHANNEL_INCOGNITO_MODE,
                    ) {
                        setContentTitle(stringResource(MR.strings.pref_incognito_mode))
                        setContentText(stringResource(MR.strings.notification_incognito_text))
                        setSmallIcon(R.drawable.ic_glasses_24dp)
                        setOngoing(true)

