    /** Область сканирования страницы. */
    SCAN_REGION("scan_region", "Область сканирования"),

    /** Режим чтения (вьюер). */
    READING_MODE("reading_mode", "Режим чтения"),

    /** Движок озвучки. */
    VOICE_ENGINE("voice_engine", "Движок озвучки"),

    /** Провайдер AI-чата. */
    AI_PROVIDER("ai_provider", "Провайдер AI-чата"),
