    val rule = yomikai.data.ai.BookLearning
        .lastOf(rules, yomikai.data.ai.BookLearning.KIND_BUBBLE)
        ?: return false
    val text = rule.text.lowercase()
    return BUBBLES_ONLY_MARKERS.any { it in text }
}

