import android.graphics.Rect
import androidx.core.graphics.createBitmap
import com.google.ai.edge.litert.Accelerator
import com.google.ai.edge.litert.CompiledModel
import com.google.ai.edge.litert.Environment
import com.google.ai.edge.litert.TensorBuffer
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import logcat.LogPriority
import yomikai.domain.panel.model.DebugPanelDetection
import yomikai.domain.panel.model.PanelDetectionResult
import yomikai.domain.panel.repository.PanelDetectionRepository
import yomikai.core.common.util.system.Panel
import yomikai.core.common.util.system.ReadingDirection
import yomikai.core.common.util.system.ReadingOrderSorter
import yomikai.core.common.util.system.logcat
import java.io.Closeable
import kotlin.math.abs
import kotlin.math.max
import kotlin.math.roundToInt
import kotlin.system.measureNanoTime

class PanelDetectionRepositoryImpl(
    private val context: Context,
    /**
     * Optional provider downloads the panel detector outside the APK on first
     * use. The Cyrillic OCR text detector is separate from this panel model.
     */
    private val embeddedModelProvider: (suspend () -> String?)? = null,
) : PanelDetectionRepository {

    private val environment by lazy { Environment.create() }

    private var engine: YoloPanelDetectionEngine? = null
    private val engineMutex = Mutex()

    private suspend fun getEngine(): YoloPanelDetectionEngine {
        return engineMutex.withLock {
            engine ?: run {
                val modelPath = yomikai.data.ocr.OcrModelFiles.resolve(context, EXTERNAL_MODEL_PATH)
                    ?: embeddedModelProvider?.invoke()
                    ?: error(
                        "Panel detector model not found: install externally " +
                            "(ocr_models/panel_detector.tflite) or embedded pack failed",
                    )
                YoloPanelDetectionEngine(context, environment, modelPath).also { engine = it }
            }
        }
    }

    private companion object {
        const val EXTERNAL_MODEL_PATH = "panel_detector/model.tflite"
    }

    override suspend fun detectPanels(
        cacheKey: String,
        image: Bitmap,
        originalWidth: Int,
        originalHeight: Int,
        direction: ReadingDirection,
    ): PanelDetectionResult {
        return try {
            getEngine().detectPanels(
                cacheKey = cacheKey,
                image = image,
                originalWidth = originalWidth,
                originalHeight = originalHeight,
                direction = direction,
            )
        } catch (e: CancellationException) {
            throw e
        } catch (e: Throwable) {
            logcat(LogPriority.WARN, e) { "Panel detection failed for $cacheKey" }
            PanelDetectionResult.EMPTY
        }
    }

    override fun cleanup() {
        try {
            engine?.close()
            engine = null
            logcat(LogPriority.INFO) { "PanelDetectionRepositoryImpl cleaned up successfully" }
        } catch (e: Exception) {
            logcat(LogPriority.ERROR, e) { "Error cleaning up panel detector" }
        }
    }
}

private class YoloPanelDetectionEngine(
    private val context: Context,
    environment: Environment,
    private val modelFilePath: String,
) : Closeable {

    private val compiledModel: CompiledModel
    private val inputBuffers: List<TensorBuffer>
    private val outputBuffers: List<TensorBuffer>
    private val inferenceMutex = Mutex()

    private val scratchBitmap = createBitmap(INPUT_SIZE, INPUT_SIZE)
    private val scratchCanvas = Canvas(scratchBitmap)
    private val scratchPaint = Paint(Paint.FILTER_BITMAP_FLAG or Paint.DITHER_FLAG).apply {
        isAntiAlias = true
    }
    private val sourceRect = Rect()
    private val destinationRect = Rect()
    private val pixelBuffer = IntArray(INPUT_SIZE * INPUT_SIZE)
    private val inputFloatBuffer = FloatArray(INPUT_SIZE * INPUT_SIZE * 3)

    private val cache = object : LinkedHashMap<String, PanelDetectionResult>(CACHE_CAPACITY, 0.75f, true) {
        override fun removeEldestEntry(eldest: MutableMap.MutableEntry<String, PanelDetectionResult>?): Boolean {
            return size > CACHE_CAPACITY
        }
    }
    private val cacheMutex = Mutex()

    init {
        val modelFile = modelFilePath

        val cpuThreads = Runtime.getRuntime().availableProcessors().coerceIn(2, 4)
        val options = CompiledModel.Options(Accelerator.CPU).apply {
            cpuOptions = CompiledModel.CpuOptions(cpuThreads, null, null)
        }

        compiledModel = CompiledModel.create(
            modelFile,
            options,
            environment,
        )
        inputBuffers = compiledModel.createInputBuffers()
        outputBuffers = compiledModel.createOutputBuffers()
        check(inputBuffers.size == 1) { "Panel detector expected 1 input but found ${inputBuffers.size}" }
        check(outputBuffers.isNotEmpty()) { "Panel detector expected at least 1 output buffer" }

        logcat(LogPriority.INFO) {
            "Panel detector initialized (cpuThreads=$cpuThreads, outputs=${outputBuffers.size})"
        }
    }

    suspend fun detectPanels(
        cacheKey: String,
        image: Bitmap,
        originalWidth: Int,
        originalHeight: Int,
        direction: ReadingDirection,
    ): PanelDetectionResult {
        cacheMutex.withLock {
            cache[cacheEntryKey(cacheKey, direction)]?.let {
                return it.copy(cacheHit = true)
            }
        }

        var preprocessNanos = 0L
        var inferenceNanos = 0L
        val detections = mutableListOf<ScoredDetection>()

        val totalStart = System.nanoTime()
        inferenceMutex.withLock {
            val preprocessing = preprocessImage(
                image = image,
                originalWidth = originalWidth,
                originalHeight = originalHeight,
            )
            preprocessNanos = preprocessing.durationNanos

            inputBuffers[0].writeFloat(inputFloatBuffer)

            inferenceNanos = measureNanoTime {
                compiledModel.run(inputBuffers, outputBuffers)
            }

            val rawOutputs = outputBuffers.map { it.readFloat() }

            detections += parseDetections(
                rawOutputs = rawOutputs,
                mapping = preprocessing.mapping,
                originalWidth = originalWidth,
                originalHeight = originalHeight,
            )
        }
        val totalNanos = System.nanoTime() - totalStart

        val result = buildResult(
            cacheKey = cacheKey,
            originalWidth = originalWidth,
            originalHeight = originalHeight,
            direction = direction,
            preprocessNanos = preprocessNanos,
            inferenceNanos = inferenceNanos,
            totalNanos = totalNanos,
            detections = detections,
        )

        cacheMutex.withLock {
            cache[cacheEntryKey(cacheKey, direction)] = result
        }
        return result
    }

    private fun buildResult(
        cacheKey: String,
        originalWidth: Int,
        originalHeight: Int,
        direction: ReadingDirection,
        preprocessNanos: Long,
        inferenceNanos: Long,
        totalNanos: Long,
        detections: List<ScoredDetection>,
    ): PanelDetectionResult {
        val panelDetections = detections.filter { it.classId == PANEL_CLASS_ID }
        val bubbleDetections = detections.filter {
            it.classId == BUBBLE_CLASS_ID && it.confidence >= BUBBLE_CONFIDENCE_THRESHOLD
        }

        val prunedPanels = removeHeavyOverlaps(
            panelDetections
                .filter { it.confidence >= CONFIDENCE_THRESHOLD }
                .filter { it.rect.width() > 0 && it.rect.height() > 0 }
                .filter { isLargeEnough(it.rect, originalWidth, originalHeight) },
        )
        val prunedBubbles = removeHeavyOverlaps(
            bubbleDetections
                .filter { it.rect.width() > 0 && it.rect.height() > 0 },
        )

        val debugPanels = prunedPanels
            .sortedByDescending { it.confidence }
            .map { DebugPanelDetection(rect = Rect(it.rect), confidence = it.confidence) }
        val debugBubbles = prunedBubbles
            .sortedByDescending { it.confidence }
            .map { DebugPanelDetection(rect = Rect(it.rect), confidence = it.confidence) }

        val orderedRects = sortByReadingOrder(
            rects = prunedPanels.map { it.rect },
            direction = direction,
        )
        val expandedRects = expandLargePanels(
            panels = orderedRects,
            bubbles = prunedBubbles.map { it.rect },
            imageWidth = originalWidth,
            imageHeight = originalHeight,
            direction = direction,
        )
        val orderedPanels = expandedRects.map(::Panel)

        val result = PanelDetectionResult(
            panels = orderedPanels,
            debugPanels = debugPanels,
            debugBubbles = debugBubbles,
            preprocessMillis = preprocessNanos / 1_000_000,
            inferenceMillis = inferenceNanos / 1_000_000,
            totalMillis = totalNanos / 1_000_000,

package yomikai.data.ocr

import android.graphics.Bitmap
import android.graphics.Rect
import yomikai.domain.chapter.model.toSChapter
import yomikai.data.download.DownloadManager
import yomikai.data.download.model.Download
import yomikai.source.Source
import yomikai.source.model.Page
import yomikai.source.online.HttpSource
import kotlinx.coroutines.flow.filterNotNull
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.withTimeoutOrNull
import yomikai.core.common.util.lang.withIOContext
import yomikai.domain.chapter.model.Chapter
import yomikai.domain.manga.model.Manga
import yomikai.domain.source.service.SourceManager
import yomikai.source.local.LocalSource
import java.io.InputStream
import kotlin.time.Duration.Companion.seconds

internal class OcrPageSourceResolver(
    private val sourceManager: SourceManager,
    private val downloadManager: DownloadManager,
    private val pageSourceGateway: OcrPageSourceGateway,
) {
    suspend fun resolve(
        manga: Manga,
        chapter: Chapter,
    ): ResolvedOcrPages {
        val source = sourceManager.getOrStub(manga.source)
        val downloadedPagesReady = if (source is HttpSource) {
            awaitDownloadedChapterPages(manga, chapter)
        } else {
            false
        }
        return when {
            downloadedPagesReady -> resolveDownloadedPages(manga, chapter, source)
            source is LocalSource -> resolveLocalPages(source, chapter)
            source is HttpSource -> resolveRemotePages(source, chapter)
            else -> ResolvedOcrPages(emptyList())
        }
    }

    private suspend fun awaitDownloadedChapterPages(
        manga: Manga,
        chapter: Chapter,
    ): Boolean {
        val queuedDownload = downloadManager.getQueuedDownloadOrNull(chapter.id)
        if (queuedDownload == null) {
            return isChapterDownloaded(manga, chapter)
        }

        return withTimeoutOrNull(DOWNLOAD_WAIT_TIMEOUT.inWholeMilliseconds) {
            queuedDownload.statusFlow
                .map { status ->
                    val isStillQueued = downloadManager.getQueuedDownloadOrNull(chapter.id) != null
                    val downloaded = isChapterDownloaded(manga, chapter)
                    when {
                        downloaded && !isStillQueued -> true
                        status == Download.State.ERROR || status == Download.State.NOT_DOWNLOADED -> false
                        else -> null
                    }
                }
                .filterNotNull()
                .first()
        } ?: false
    }

    private fun isChapterDownloaded(
        manga: Manga,
        chapter: Chapter,
    ): Boolean {
        return downloadManager.isChapterDownloaded(
            chapter.name,
            chapter.scanlator,
            chapter.url,
            manga.title,
            manga.source,
            skipCache = true,
        )
    }

    private suspend fun resolveDownloadedPages(
        manga: Manga,
        chapter: Chapter,
        source: Source,
    ): ResolvedOcrPages {
        return pageSourceGateway.resolveDownloadedPages(manga, chapter, source)
    }

    private suspend fun resolveLocalPages(
        source: LocalSource,
        chapter: Chapter,
    ): ResolvedOcrPages {
        return pageSourceGateway.resolveLocalPages(source, chapter)
    }

    private suspend fun resolveRemotePages(
        source: HttpSource,
        chapter: Chapter,
    ): ResolvedOcrPages {
        val pages = source.getPageList(chapter.toSChapter())
            .mapIndexed { index, page -> Page(index, page.url, page.imageUrl, page.uri) }
            .map { page ->
                OcrPageInput(
                    pageIndex = page.index,
                    openBitmap = {
                        decodeOcrBitmapWithFallback { decode ->
                            openRemotePageBitmap(page, source, decode)
                        }
                    },
                    openBitmapRegion = { sourceRect ->
                        decodeOcrRegionWithFallback(sourceRect) { decode ->
                            openRemotePageBitmap(page, source, decode)
                        }
                    },
                )
            }

        return ResolvedOcrPages(pages)
    }

    private suspend fun <T> openRemotePageBitmap(
        page: Page,
        source: HttpSource,
        decode: (InputStream) -> T?,
    ): T? {
        return withIOContext {
            if (page.imageUrl.isNullOrBlank()) {
                page.imageUrl = source.getImageUrl(page)
            }
            source.getImage(page).use { response ->
                decode(response.body.byteStream())
            }
        }
    }
}

private val DOWNLOAD_WAIT_TIMEOUT = 15.seconds

data class OcrPageInput(
    val pageIndex: Int,
    val openBitmap: suspend () -> Bitmap?,
    val openBitmapRegion: suspend (Rect) -> Bitmap?,
)

internal class ResolvedOcrPages(
    val pages: List<OcrPageInput>,
    private val closeBlock: () -> Unit = {},
) : AutoCloseable {
    fun getPageInput(pageIndex: Int): OcrPageInput? {
        return pages.firstOrNull { it.pageIndex == pageIndex }
    }

    override fun close() {
        closeBlock()
    }
}

package yomikai.data.ocr

import android.content.Context
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch
import kotlinx.serialization.Serializable
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import logcat.LogPriority
import yomikai.core.common.util.system.logcat
import java.io.File

/**
 * Журналы авточтения и сканирования для экрана истории — продвинутая версия.
 *
 * Что изменилось по запросу:
 *  - История сканирования — была in-memory (терялась при перезапуске), теперь
 *    персистентная: JSON на диске + StateFlow, лимит 500, survive reboot
 *  - Автоочистка по времени (30 дней) и по размеру
 *  - Экспорт/импорт истории через workspace/history/
 *  - Потоковый апдейт: пока OCR идёт по тайлам, запись обновляется,
 *    а не только в конце
 *  - Фильтры по успеху/дате в UI (через `filteredScans(okOnly)`)
 *  - Сохраняются и стрим-события (partial), чтобы видеть прогресс
 */
object OcrHistoryStore {

    private const val MAX_ENTRIES = 500
    private const val FILE_NAME = "ocr_history.json"
    private const val RETENTION_MS = 30L * 24 * 60 * 60 * 1000 // 30 дней

    @Serializable
    data class ScanEntry(
        val time: Long,
        val ok: Boolean,
        val detail: String,
        val wordDictHits: Int = 0,
        val punctFixes: Int = 0,
        val splitFixes: Int = 0,
        val isStreaming: Boolean = false,
        val page: String = "",
    )

    @Serializable
    data class AutoReadEntry(
        val time: Long,
        val ok: Boolean,
        val event: String,
        val detail: String,
        val voice: String = "",
        val durationMs: Long = 0,
    )

    @Serializable
    private data class Persisted(
        val scans: List<ScanEntry> = emptyList(),
        val reads: List<AutoReadEntry> = emptyList(),
    )

    private val json = Json { ignoreUnknownKeys = true; encodeDefaults = true; prettyPrint = false }

    private val _scans = MutableStateFlow<List<ScanEntry>>(emptyList())
    val scans: StateFlow<List<ScanEntry>> = _scans

    private val _reads = MutableStateFlow<List<AutoReadEntry>>(emptyList())
    val reads: StateFlow<List<AutoReadEntry>> = _reads

    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)
    private var persistFile: File? = null
    private var initialized = false

    fun init(context: Context) {
        if (initialized) return
        initialized = true
        val file = File(context.filesDir, FILE_NAME)
        persistFile = file
        scope.launch {
            runCatching {
                if (file.exists()) {
                    val raw = file.readText()
                    val data = json.decodeFromString<Persisted>(raw)
                    val cutoff = System.currentTimeMillis() - RETENTION_MS
                    _scans.value = data.scans.filter { it.time >= cutoff }.take(MAX_ENTRIES)
                    _reads.value = data.reads.filter { it.time >= cutoff }.take(MAX_ENTRIES)
                }
            }.onFailure { e -> logcat(LogPriority.WARN, e) { "OcrHistoryStore load failed" } }
        }
    }

    private fun persist() {
        val file = persistFile ?: return
        scope.launch {
            runCatching {
                val data = Persisted(_scans.value.take(MAX_ENTRIES), _reads.value.take(MAX_ENTRIES))
                file.writeText(json.encodeToString(data))
            }.onFailure { e -> logcat(LogPriority.WARN, e) { "OcrHistoryStore persist failed" } }
        }
    }

    @Synchronized
    fun addScan(
        ok: Boolean,
        detail: String,
        wordDictHits: Int = 0,
        punctFixes: Int = 0,
        splitFixes: Int = 0,
        isStreaming: Boolean = false,
        page: String = "",
    ) {
        val entry = ScanEntry(
            System.currentTimeMillis(), ok, detail, wordDictHits, punctFixes, splitFixes, isStreaming, page,
        )
        _scans.value = (listOf(entry) + _scans.value).take(MAX_ENTRIES)
        persist()
    }

    @Synchronized
    fun addStreamingScan(partialDetail: String, page: String = "") {
        addScan(ok = true, detail = partialDetail, isStreaming = true, page = page)
    }

    @Synchronized
    fun addAutoRead(ok: Boolean, event: String, detail: String, voice: String = "", durationMs: Long = 0) {
        val entry = AutoReadEntry(System.currentTimeMillis(), ok, event, detail, voice, durationMs)
        _reads.value = (listOf(entry) + _reads.value).take(MAX_ENTRIES)
        persist()
    }

    // Legacy overload for existing call sites
    @Synchronized
    fun addAutoRead(ok: Boolean, event: String, detail: String) {
        addAutoRead(ok, event, detail, voice = "", durationMs = 0)
    }

    @Synchronized
    fun addScan(ok: Boolean, detail: String, wordDictHits: Int, punctFixes: Int, splitFixes: Int) {
        addScan(ok, detail, wordDictHits, punctFixes, splitFixes, isStreaming = false, page = "")
    }

    fun filteredScans(okOnly: Boolean = false, query: String = ""): List<ScanEntry> {
        var list = _scans.value
        if (okOnly) list = list.filter { it.ok }
        if (query.isNotBlank()) {
            val q = query.lowercase()
            list = list.filter { it.detail.lowercase().contains(q) || it.page.lowercase().contains(q) }
        }
        return list
    }

    fun filteredReads(query: String = ""): List<AutoReadEntry> {
        if (query.isBlank()) return _reads.value
        val q = query.lowercase()
        return _reads.value.filter { it.event.lowercase().contains(q) || it.detail.lowercase().contains(q) }
    }

    @Synchronized
    fun clearAll() {
        _scans.value = emptyList()
        _reads.value = emptyList()
        persist()
    }

    @Synchronized
    fun clearScans() {
        _scans.value = emptyList()
        persist()
    }

    @Synchronized
    fun clearReads() {
        _reads.value = emptyList()
        persist()
    }

    fun export(context: Context): File? {
        return try {
            val dir = File(context.getExternalFilesDir(null), "history").apply { mkdirs() }
            val out = File(dir, "ocr_history_${System.currentTimeMillis()}.json")
            val data = Persisted(_scans.value, _reads.value)
            out.writeText(json.encodeToString(data))
            out
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "OcrHistoryStore export failed" }
            null
        }
    }
}

