fun processOcrRegion(bitmap: Bitmap) {
    viewModelScope.launchIO {
        mutableState.update { it.copy(isProcessingOcr = true, ocrSelectionMode = false) }
        try {
            val work = prepareCropForOcr(bitmap)
            val text = try {
                ocrProcessor.getText(work.toOcrImage())
            } finally {
                if (work !== bitmap) work.recycle()
            }
            // Читаем ПОСЛЕ распознавания: без сети онлайн-движок
            // пропускается, и текст читает локальный. Показываем
            // фактического исполнителя, иначе «онлайн» — враньё.
            val usedEngine = ocrProcessor.lastUsedEngine()
            val queryText = flattenOcrTextForQuery(text)
            // Помечаем результат так же, как это делает авточтение: запись
            // в буфер «Скриншоты» с кадром области. Раньше ручной выбор
            // regions нигде не оставался — распознал, посмотрел, закрыл, и
            // результат потерян, а вкладка «Скриншоты» показывала только
            // кадры авточтения.
            val marked = if (queryText.isNotBlank()) {
                markRecognizedRegion(bitmap, queryText, usedEngine)
            } else {
                false
            }
            withUIContext {
                if (queryText.isNotBlank()) {
                    showOcrResult(
                        queryText = queryText,
                        origin = OcrResultOrigin.ManualSelection,
                        source = ocrSource(usedEngine),
                    )
                    mutableState.update { it.copy(isProcessingOcr = false) }
                    if (marked) {
                        eventChannel.send(Event.OcrResultMarked)
                    }
                } else {
                    mutableState.update { it.copy(isProcessingOcr = false) }
                    eventChannel.send(Event.OcrNoTextFound)
                }
            }
        } catch (e: CancellationException) {
            // Handle coroutine cancellation (e.g., user navigates away)
            logcat(LogPriority.DEBUG) { "OCR processing cancelled" }
            withUIContext {
                mutableState.update { it.copy(isProcessingOcr = false) }
            }

package yomikai.ui.reader

import android.graphics.Bitmap
import android.graphics.Canvas
import android.graphics.RectF
import androidx.core.graphics.createBitmap
import yomikai.data.database.models.toDomainChapter
import yomikai.data.ocr.OcrPageInput
import yomikai.data.ocr.OcrPageSourceResolver
import yomikai.data.ocr.ResolvedOcrPages
import yomikai.data.ocr.openCroppedBitmap
import yomikai.ui.reader.viewer.ReaderSelectionCapture
import logcat.LogPriority
import yomikai.core.common.util.system.logcat
import yomikai.domain.chapter.model.Chapter
import yomikai.domain.manga.model.Manga

internal class ReaderSelectionCropper(
    private val ocrPageSourceResolver: OcrPageSourceResolver,
) {
    suspend fun cropSelectionBitmap(
        manga: Manga,
        captures: List<ReaderSelectionCapture>,
        shape: yomikai.data.ocr.ScanShape = yomikai.data.ocr.ScanShape.RECT,
    ): Bitmap? {
        val resolvedPagesByChapter = mutableMapOf<Chapter, ResolvedOcrPages>()
        try {
            if (captures.size == 1) {
                return cropPageBitmap(manga, captures.first(), resolvedPagesByChapter)?.let { clipToShape(it, shape) }
            }

            logcat(LogPriority.DEBUG) {
                "Selection crop stitching ${captures.size} page segments"
            }

            val parts = captures.mapNotNull { capture ->
                cropPageBitmap(manga, capture, resolvedPagesByChapter)?.let { bitmap ->
                    CroppedSelectionPart(
                        bitmap = bitmap,
                        screenRect = capture.screenRect,
                    )
                }
            }

            if (parts.isEmpty()) {
                logcat(LogPriority.WARN) {
                    "Selection crop unavailable for all ${captures.size} page segments"
                }
                return null
            }

            try {
                val minLeft = parts.minOf { it.screenRect.left }
                val minTop = parts.minOf { it.screenRect.top }
                val positionedParts = parts.map { part ->
                    PositionedSelectionPart(
                        bitmap = part.bitmap,
                        left = part.screenRect.left - minLeft,
                        top = part.screenRect.top - minTop,
                    )
                }
                val mergedWidth = positionedParts
                    .maxOf { it.left + it.bitmap.width }
                    .toInt()
                    .coerceAtLeast(1)
                val mergedHeight = positionedParts
                    .maxOf { it.top + it.bitmap.height }
                    .toInt()
                    .coerceAtLeast(1)
                val mergedBitmap = createBitmap(mergedWidth, mergedHeight)
                val canvas = Canvas(mergedBitmap)

                positionedParts.forEach { part ->
                    canvas.drawBitmap(part.bitmap, part.left, part.top, null)
                }

                logcat(LogPriority.DEBUG) {
                    "Selection crop stitched bitmap size=${mergedBitmap.width}x${mergedBitmap.height}"
                }
                return clipToShape(mergedBitmap, shape)
            } finally {
                parts.forEach { part ->
                    if (!part.bitmap.isRecycled) {
                        part.bitmap.recycle()
                    }
                }
            }
        } finally {
            resolvedPagesByChapter.values.forEach(ResolvedOcrPages::close)
        }
    }

    private suspend fun cropPageBitmap(
        manga: Manga,
        capture: ReaderSelectionCapture,
        resolvedPagesByChapter: MutableMap<Chapter, ResolvedOcrPages>,
    ): Bitmap? {
        val page = capture.page
        val sourceRect = capture.sourceRect
        val chapter = page.chapter.chapter.toDomainChapter()
            ?: throw IllegalStateException("Chapter unavailable")

        capture.decodeBitmap()?.let { bitmap ->
            logcat(LogPriority.DEBUG) {
                "Selection crop page=${page.index} via loaded source size=${bitmap.width}x${bitmap.height}"
            }
            return bitmap
        }

        val pageInput = getPageInput(
            manga = manga,
            chapter = chapter,
            pageIndex = page.index,
            resolvedPagesByChapter = resolvedPagesByChapter,
        )

        pageInput.openCroppedBitmap(sourceRect)?.let { bitmap ->
            logcat(LogPriority.DEBUG) {
                "Selection crop page=${page.index} via OCR source size=${bitmap.width}x${bitmap.height}"
            }
            return bitmap
        }

        logcat(LogPriority.WARN) {
            "Selection crop page=${page.index} unavailable"
        }
        return null
    }

    /**
     * Обрезка по фигурной рамке: вне пути фигуры текст не распознаётся.
     * RECT — без изменений; любая ошибка клипа = безопасный фолбэк в прямоугольник.
     */
    private fun clipToShape(bitmap: Bitmap, shape: yomikai.data.ocr.ScanShape): Bitmap {
        if (shape == yomikai.data.ocr.ScanShape.RECT) return bitmap
        return try {
            val out = Bitmap.createBitmap(bitmap.width, bitmap.height, Bitmap.Config.ARGB_8888)
            val canvas = Canvas(out)
            canvas.clipPath(shape.buildPath(RectF(0f, 0f, bitmap.width.toFloat(), bitmap.height.toFloat())))
            canvas.drawBitmap(bitmap, 0f, 0f, null)
            out
        } catch (t: Throwable) {
            logcat(LogPriority.WARN, t) { "Shape clip failed; fallback to rect" }
            bitmap
        }
    }

    private suspend fun getPageInput(
        manga: Manga,
        chapter: Chapter,
        pageIndex: Int,
        resolvedPagesByChapter: MutableMap<Chapter, ResolvedOcrPages>,
    ): OcrPageInput {
        val resolvedPages = resolvedPagesByChapter[chapter]
            ?: ocrPageSourceResolver.resolve(manga, chapter).also { resolvedPagesByChapter[chapter] = it }
        return resolvedPages.getPageInput(pageIndex)
            ?: throw IllegalStateException("Page unavailable for crop")
    }
}

private data class CroppedSelectionPart(
    val bitmap: Bitmap,
    val screenRect: RectF,
)

private data class PositionedSelectionPart(
    val bitmap: Bitmap,
    val left: Float,
    val top: Float,
)

package yomikai.data.ocr

/**
 * Utility for converting OCR Latin confusion / transliterated text into proper Cyrillic script.
 */
object CyrillicTranslitFixer {

    private val LOOKALIKE_MAP = mapOf(
        'A' to 'А', 'a' to 'а',
        'B' to 'В',
        'C' to 'С', 'c' to 'с',
        'E' to 'Е', 'e' to 'е',
        'H' to 'Н',
        'K' to 'К', 'k' to 'к',
        'M' to 'М',
        'O' to 'О', 'o' to 'о',
        'P' to 'Р', 'p' to 'р',
        'T' to 'Т',
        'X' to 'Х', 'x' to 'х',
        'y' to 'у',
        '3' to 'З',
        '6' to 'б',
    )

    private val TRANSLIT_MULTI_MAP = listOf(
        "shch" to "щ", "SHCH" to "Щ", "Shch" to "Щ",
        "ch" to "ч", "CH" to "Ч", "Ch" to "Ч",
        "sh" to "ш", "SH" to "Ш", "Sh" to "Ш",
        "zh" to "ж", "ZH" to "Ж", "Zh" to "Ж",
        "yo" to "ё", "YO" to "Ё", "Yo" to "Ё", "jo" to "ё",
        "ya" to "я", "YA" to "Я", "Ya" to "Я", "ja" to "я",
        "yu" to "ю", "YU" to "Ю", "Yu" to "Ю", "ju" to "ю",
        "ye" to "е", "YE" to "Е", "Ye" to "Е",
        "ts" to "ц", "TS" to "Ц", "Ts" to "Ц",
        "kh" to "х", "KH" to "Х", "Kh" to "Х",
    )

    private val TRANSLIT_SINGLE_MAP = mapOf(
        'a' to "а", 'b' to "б", 'v' to "в", 'g' to "г", 'd' to "д",
        'e' to "е", 'z' to "з", 'i' to "и", 'k' to "к", 'l' to "л",
        'm' to "м", 'n' to "н", 'o' to "о", 'p' to "п", 'r' to "р",
        's' to "с", 't' to "т", 'u' to "у", 'f' to "ф", 'h' to "х",
        'y' to "ы", 'j' to "й", 'w' to "в", 'q' to "к", 'x' to "кс",
        'A' to "А", 'B' to "Б", 'V' to "В", 'G' to "Г", 'D' to "Д",
        'E' to "Е", 'Z' to "З", 'I' to "И", 'K' to "К", 'L' to "Л",
        'M' to "М", 'N' to "Н", 'O' to "О", 'P' to "П", 'R' to "Р",
        'S' to "С", 'T' to "Т", 'U' to "У", 'F' to "Ф", 'H' to "Х",
        'Y' to "Ы", 'J' to "Й", 'W' to "В", 'Q' to "К",
    )

    /**
     * Fixes OCR visual confusion where Cyrillic letters were recognized as Latin lookalikes.
     */
    fun fixLookalikes(text: String): String {
        val sb = StringBuilder(text.length)
        for (char in text) {
            sb.append(LOOKALIKE_MAP[char] ?: char)
        }
        return sb.toString()
    }

    /**
     * Converts transliterated Latin script into Cyrillic script.
     */
    fun translitToCyrillic(text: String): String {
        var result = text
        for ((latin, cyrillic) in TRANSLIT_MULTI_MAP) {
            result = result.replace(latin, cyrillic)
        }

        val sb = StringBuilder(result.length * 2)
        for (char in result) {
            val mapped = TRANSLIT_SINGLE_MAP[char]
            if (mapped != null) {
                sb.append(mapped)
            } else {
                sb.append(char)
            }
        }
        return sb.toString()
    }

    /**
     * Automatically fixes transliteration or Latin lookalikes for Russian text.
     *
     * Приоритет — омоглиф-фикс, а не транслитерация. Локальный CTC-модель на
     * манге выдаёт кириллическое слово латинскими омоглифами (Х→X, А→A, Н→H),
     * и старая логика для чисто латинской строки сразу вызывала
     * [translitToCyrillic], превращая «XAA» в «ксАА» (X→кс): буквы «рассыпа-
     * лись» и TTS диктовал бессмыслицу. Теперь сначала пробуем [fixLookalikes]
     * (X→Х, A→А); если после него латиницы не осталось — строка и есть
     * омоглифная кириллица и берётся как есть. Транслитерация остаётся
     * запасным путём, только когда омоглифы не легли, а слово реально
     * транслитерировано. Настоящую латиницу (англ. надпись / звукоподражание),
     * которую не прочитать ни так, ни эдак, не трогаем — не выдумываем
     * несуществующее русское слово.
     */
    fun autoFixCyrillic(text: String): String {
        if (text.isBlank()) return text

        val latinCount = text.count { it in 'a'..'z' || it in 'A'..'Z' }
        val cyrillicCount = text.count { it in '\u0400'..'\u04FF' }

        return when {
            latinCount > 0 && cyrillicCount > 0 -> fixLookalikes(text)
            latinCount > 0 -> {
                val lookalike = fixLookalikes(text)
                val leftoverLatin = lookalike.count { it in 'a'..'z' || it in 'A'..'Z' }
                when {
                    // Все буквы легли в омоглифы → это кириллица, читаем её.
                    leftoverLatin == 0 -> lookalike
                    // Целое слово (без пробелов), которое транслитерацией
                    // ПОЛНОСТЬЮ становится кириллицей (напр. "Mibli" -> "Мибли").
                    // Раньше здесь возвращался исходный латинский текст, и TTS
                    // диктовал его по буквам («эм и бэ эл и»). Для русского
                    // чтения лучше прочитать слово по-русски, чем по буквам.
                    !text.any { it == ' ' || it == '\n' || it == '\t' } &&
                        translitToCyrillic(text).none { it in 'a'..'z' || it in 'A'..'Z' } ->
                        translitToCyrillic(text)
                    // Часть легла, часть нет → смесь; не угадываем (иначе
                    // портили бы настоящую латинскую надпись). Оставляем как есть.
                    lookalike.count { it in '\u0400'..'\u04FF' } > 0 -> text
                    // Омоглифы не подошли совсем → пробуем честную транслитерацию.
                    else -> translitToCyrillic(text)
                }
            }
            else -> text
        }
    }
}

package yomikai.data.ocr

/**
 * Частотный словарь русских словоформ для разбиения слипшегося OCR-текста
 * на слова (только вставка пробелов, без замены символов — словарная
 * «коррекция» запрещена правилами проекта).
 *
 * Собран из открытых текстов (русские классические рассказы/пьесы,
 * wikisource) плюс диалоговые сиды под речь манги. Частотный порог >=2
 * вхождений в корпусе; ручные сиды добавлены безусловно.
 */
object RuWordList {

    private val parts: Array<Array<String>> = arrayOf(
        ruWordListPart000(),
        ruWordListPart001(),
        ruWordListPart002(),
    )

    /** Словоформы ВЕРХНИМ регистром: прогоны OCR приходят капсом. */
    val upper: Set<String> by lazy {
        val set = HashSet<String>(parts.sumOf { it.size } * 2)
        for (part in parts) for (w in part) set.add(w.uppercase())
        set
    }

    val lower: Set<String> by lazy {
        val set = HashSet<String>(parts.sumOf { it.size } * 2)
        for (part in parts) for (w in part) set.add(w)
        set
    }
}

package yomikai.data.ocr

import android.content.Context

/**
 * Публичная проверка доступности OCR-плагинов для UI.
 *
 * Экраны настроек живут в модуле `app`, а `OcrModelFiles` и
 * `CyrillicOcrEngine` — `internal` в модуле `data`. Чтобы UI не тянул внутренности
 * движка и не дублировал список файлов пакета моделей, проверка собирается
 * здесь и отдаётся уже готовым множеством id.
 */
object OcrPluginAvailability {

    /**
     * Id плагинов, которые можно использовать прямо сейчас.
     *
     * @param networkAvailable есть ли интернет;
     * @param hasApiKey есть ли ключ у плагина (OpenRouter / Google AI);
     * @param hasServerAddress задан ли адрес своего сервера (OwOCR).
     */
    fun availableIds(
        context: Context,
        networkAvailable: Boolean,
        hasApiKey: (OcrPluginDescriptor) -> Boolean = { false },
        hasServerAddress: (OcrPluginDescriptor) -> Boolean = { false },
    ): Set<String> {
        val litertAvailable = runCatching {
            com.google.ai.edge.litert.Environment.create().close()
        }.isSuccess
        val modelsInstalled = OcrModelFiles.allInstalled(
            context,
            listOf(
                CyrillicOcrEngine.DETECTOR_PATH,
                CyrillicOcrEngine.PRIMARY_PATH,
                CyrillicOcrEngine.PRIMARY_DICT_PATH,
            ),
        )
        return OcrPlugins.available(
            networkAvailable = networkAvailable,
            modelsInstalled = modelsInstalled,
            litertAvailable = litertAvailable,
            hasApiKey = hasApiKey,
            hasServerAddress = hasServerAddress,
        ).map { it.id }.toSet()
    }

    /** Причина недоступности одним текстом — для подзаголовка в настройках. */
    fun missingRequirement(
        plugin: OcrPluginDescriptor,
        availableIds: Set<String>,
    ): OcrPluginRequirement? {
        if (plugin.id in availableIds) return null
        return plugin.requirements.firstOrNull()
    }
}

