package yomikai.data.ocr

import android.app.NotificationChannel
import android.app.NotificationManager
import android.content.Context
import android.os.Build
import androidx.core.app.NotificationCompat
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import logcat.LogPriority
import yomikai.core.common.util.system.logcat

/**
 * Шторка уведомлений для распознанного текста.
 *
 * Запрос пользователя: «уменьш оверлей распознаного текста либо вынеси в шторку уведомлений».
 * Решение:
 *  - Оверлей по умолчанию — компактный (320dp карточка), а не на 70% экрана
 *  - Опция `pref_ocr_to_notification` дублирует распознанный текст в Notification
 *    с действиями Копировать / Озвучить / Закрыть — не перекрывает читалку
 *  - Стриминг: пока OCR идёт по тайлам, уведомление обновляется построчно
 */
object OcrNotificationManager {

    private const val CHANNEL_ID = "yomikai_ocr"
    private const val CHANNEL_NAME = "Распознанный текст"
    private const val NOTIF_ID = 4201

    private val _lastText = MutableStateFlow<String?>(null)
    val lastText: StateFlow<String?> = _lastText

    fun ensureChannel(context: Context) {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) return
        val nm = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        if (nm.getNotificationChannel(CHANNEL_ID) != null) return
        val channel = NotificationChannel(
            CHANNEL_ID,
            CHANNEL_NAME,
            NotificationManager.IMPORTANCE_LOW,
        ).apply {
            description = "Распознанный OCR-текст из читалки и браузера"
            setShowBadge(false)
            enableVibration(false)
            setSound(null, null)
        }
        nm.createNotificationChannel(channel)
    }

    fun show(
        context: Context,
        text: String,
        isStreaming: Boolean = false,
        onCopy: (() -> Unit)? = null,
        onSpeak: (() -> Unit)? = null,
    ) {
        if (text.isBlank()) return
        _lastText.value = text
        ensureChannel(context)
        val nm = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager

        val preview = text.take(512)
        val bigText = if (isStreaming) "$preview\n…распознаётся…" else preview

        val builder = NotificationCompat.Builder(context, CHANNEL_ID)
            .setSmallIcon(android.R.drawable.ic_menu_view)
            .setContentTitle(if (isStreaming) "Распознаётся…" else "Распознанный текст")
            .setContentText(preview.take(40))
            .setStyle(NotificationCompat.BigTextStyle().bigText(bigText))
            .setOngoing(isStreaming)
            .setOnlyAlertOnce(true)
            .setPriority(NotificationCompat.PRIORITY_LOW)
            .setCategory(NotificationCompat.CATEGORY_PROGRESS)

        // Действия добавляются через PendingIntent в Activity — здесь заглушка
        // для логгирования; реальные Intent'ы ставит ReaderActivity/BrowserTab.
        if (!isStreaming) {
            builder.addAction(0, "Копировать", null)
            builder.addAction(0, "Озвучить", null)
        }

        try {
            nm.notify(NOTIF_ID, builder.build())
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "OcrNotificationManager notify failed" }
        }
    }

    fun updateStreaming(context: Context, partialText: String) {
        show(context, partialText, isStreaming = true)
    }

    fun dismiss(context: Context) {
        val nm = context.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
        runCatching { nm.cancel(NOTIF_ID) }
        _lastText.value = null
    }
}

package yomikai.data.ocr

/**
 * Режим чтения, который соответствует пресету типа контента.
 *
 * Порядок распознавания ([OcrTuning.readingOrder]) и направление листания
 * страниц — это одна и та же сущность, описанная в двух местах: OCR режет
 * страницу по порядку чтения, а вьюер листает её в том же направлении. Если их
 * развести, «манхва» распознаётся вертикальными полосами, но листается
 * постранично справа налево, и текст собирается в кашу.
 *
 * Подсказка декларативная и живёт в `data`-модули, поэтому её можно проверить
 * unit-тестом на JVM. Конкретный вьюер (`ReadingMode`) относится к app-модули и
 * сопоставляется там же — здесь только намерение.
 */
enum class OcrViewerHint(
    val id: String,
    /** Человекочитаемое название для отчётов и подсказок в настройках. */
    val title: String,
) {
    /** Пресет не предписывает вьюер: выбор пользователя не трогаем. */
    KEEP("keep", "без изменений"),

    /** Постранично справа налево — японская манга. */
    PAGER_RTL("pager_rtl", "постранично справа налево"),

    /** Постранично слева направо — западный комикс. */
    PAGER_LTR("pager_ltr", "постранично слева направо"),

    /** Вертикальная лента — манхва и вебтуны. */
    WEBTOON("webtoon", "вертикальная лента (вебтун)"),
    ;

    companion object {
        fun fromId(id: String?): OcrViewerHint =
            entries.firstOrNull { it.id == id?.trim()?.lowercase() } ?: KEEP

        /**
         * Порядок чтения OCR → подсказка вьюера. Единственное место, где два
         * представления связаны, поэтому тест сверяет их друг с другом.
         */
        fun forReadingOrder(readingOrder: String): OcrViewerHint = when (readingOrder) {
            "rtl" -> PAGER_RTL
            "ltr" -> PAGER_LTR
            "vertical" -> WEBTOON
            else -> KEEP
        }
    }
}

